// Country outlines for MerryMapped's map: our region cut out of Natural Earth's 1:50m country
// borders (public domain, naturalearthdata.com), flattened and simplified. Generated by a one-off
// script; positions on the map come from project().

export const MAP = { width: 1000, height: 946.8 };

// Turn a position (latitude, longitude) into a point on the map, the same way the outlines were made.
export function project(lat: number, lon: number): { x: number; y: number } {
  const scale = 107.58946057226986;
  return { x: (lon - 1.2) * 0.6454576877239505 * scale, y: (54.2 - lat) * scale };
}

